// ============================================================================
// INBOUND ROUTER LUCI
// Riceve i comandi on/off/scene. Supporta topic base dinamico.
// ============================================================================

let baseTopic = global.get("app_base_topic") || "zara/android/domotica";

// Estraiamo il nome del dispositivo usando un'Espressione Regolare.
// Cerca la stringa tra "/light/" e "/set"
let regexLight = new RegExp(`^${baseTopic}/light/([^/]+)/set$`);
let matchLight = msg.topic.match(regexLight);

let device = null;
let cmd = msg.payload.toString().toUpperCase();
let targetTopic = "";
let targetPayload = cmd;
let usaLinkInterno = false;

// Gestione speciale per le scene (che non passano per /light/)
if (msg.topic.includes("/scene/set")) {
    return [msg, null]; 
}

if (matchLight && matchLight[1]) {
    device = matchLight[1];
} else {
    return null; 
}

// Normalizzazione del comando
if (cmd === "TRUE" || cmd === "1") cmd = "ON";
if (cmd === "FALSE" || cmd === "0") cmd = "OFF";
targetPayload = cmd;

switch (device) {
    case "sala":
    case "libreria":
    case "luciPiscina":
    case "luciPedanaPiscina":
    case "skimmerPiscina":
    case "ingressoServizio":
    case "pompaPiscina":
    case "tavolinoLettura":
    case "lampadaHifi":
    case "televisione":
    case "portico":
    case "lavanderia":
        targetPayload = cmd.toLowerCase();
        usaLinkInterno = true;             
        break;

    case "esterno":
        targetTopic = "shellies/shelly1-esterno/relay/0/command";
        targetPayload = cmd.toLowerCase(); 
        break;

    case "cucina":
        targetTopic = "zigbee2mqtt/Luce_Cucina/set";
        targetPayload = { state: cmd };
        break;

    default:
        node.warn("Comando App ricevuto per luce non mappata: " + device);
        return null;
}

let messaggioInUscita = {
    topic: device,
    payload: targetPayload
};

if (targetTopic !== "") {
    messaggioInUscita.topic = targetTopic;
}

if (usaLinkInterno) {
    return [null, messaggioInUscita];
} else {
    return [messaggioInUscita, null];
}

let inTopic = msg.topic;
let inPayload = msg.payload;
let baseTopic = global.get("app_base_topic") || "zara/android/domotica";

let targetDevice = "";
let deviceState = "OFF";

if (inTopic.includes("zara/domotics/lights/shelflamp")) {
    targetDevice = "libreria";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("shellies/shelly1-B8C284/relay/0")) {
    targetDevice = "lavanderia";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("shellies/shelly1-B92AF0/relay/0")) {
    targetDevice = "ingressoServizio";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("shellies/shelly1-771284/relay/0")) {
    targetDevice = "portico";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("zara/domotics/lights/poolpump")) {
    targetDevice = "pompaPiscina";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("zara/domotics/lights/poolskimmer")) {
    targetDevice = "skimmerPiscina";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("zara/domotics/lights/poolfloor")) {
    targetDevice = "luciPedanaPiscina";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("zara/domotics/lights/poollight")) {
    targetDevice = "luciPiscina";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("zara/domotics/lights/tvlamp")) {
    targetDevice = "televisione";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("zara/domotics/lights/livinglamp")) {
    targetDevice = "sala";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
} 
else if (inTopic.includes("zigbee2mqtt/Luce_Cucina")) {
    targetDevice = "cucina";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("zigbee2mqtt/Luce_Libreria")) {
    targetDevice = "libreria";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("shellies/shelly1-esterno")) {
    targetDevice = "esterno";
    deviceState = inPayload.toString().toUpperCase();
}
else if (inTopic === "zara/domotics/lights/readinglight") {
    targetDevice = "tavolinoLettura";
    deviceState = inPayload.toString().toUpperCase();
}
else {
    return null; 
}

if (deviceState === "ON" || deviceState === "on" || deviceState === "true") {
    deviceState = "ON";
} else {
    deviceState = "OFF";
}

// Generazione dinamica del topic
return {
    topic: `${baseTopic}/light/${targetDevice}/state`,
    payload: deviceState
};

// --- GATEWAY TELEMETRIE: ENERGIA E PUFFER ---
let inTopic = msg.topic;
let payload = parseFloat(msg.payload);

if (isNaN(payload)) return null;

const APP_BASE = global.get("app_base_topic", "file") || "zara/android/domotica";
let outTopic = "";
let outPayload = payload;

switch (inTopic) {

    case "TeslaPowerwall/solar_instant_power":
        outTopic = `${APP_BASE}/energy/production`;
        outPayload = Math.round(payload); 

        let ultProd = flow.get("last_prod") || 0;
        if (Math.abs(outPayload - ultProd) < 15) return null;
        flow.set("last_prod", outPayload);
        break;

    case "TeslaPowerwall/load_instant_power":
        outTopic = `${APP_BASE}/energy/consumption`;
        outPayload = Math.round(payload);

        let ultCons = flow.get("last_cons") || 0;
        if (Math.abs(outPayload - ultCons) < 15) return null;
        flow.set("last_cons", outPayload);
        break;  
     case "TeslaPowerwall/site_instant_power":
        outTopic = `${APP_BASE}/energy/grid`;
        if (Math.abs(payload) < 20) outPayload = 0;
        else outPayload = payload;
        break;    
    case "TeslaPowerwall/SOE":
        outTopic = `${APP_BASE}/energy/battery`;
        outPayload = Math.round(payload * 10) / 10;
        break;

    case "emon/shellyACS/tempACS": 
        outTopic = `${APP_BASE}/acsPufferTemp`;
        outPayload = Math.round(payload * 10) / 10;
        break;

    case "emon/resolDL2/sensor3":
        outTopic = `${APP_BASE}/pufferAltoTemp`;
        outPayload = Math.round(payload * 10) / 10;
        break;

    case "surplus":
        outTopic = `${APP_BASE}/energy/surplus`;
        outPayload = msg.payload;
        break;

    case "emon/resolDL2/sensor2":
        outTopic = `${APP_BASE}/pufferBassoTemp`;
        outPayload = Math.round(payload * 10) / 10;
        break;

    default:
        return null;
}

return {
    topic: outTopic,
    payload: outPayload.toString()
};

let baseTopic = global.get("app_base_topic") || "zara/android/domotica";

let regexThermostat = new RegExp(`^${baseTopic}/thermostat/([^/]+)/target/set$`);
let match = msg.topic.match(regexThermostat);

if (!match || !match[1]) return null;

let room = match[1];
let setpoint = parseFloat(msg.payload);

if (isNaN(setpoint)) {
    node.warn(`Setpoint non valido ricevuto per ${room}: ${msg.payload}`);
    return null;
}

let targetTopic = "";
let targetPayload = null;

switch(room) {
    case "living":
        let gradiInteri = Math.round(setpoint);
        targetTopic = "zara/domotics/AC/command";
        targetPayload = gradiInteri.toString();
        break;

    case "bathroom":
        targetTopic = "zigbee2mqtt/Termostato_Bagno/set";
        targetPayload = { current_heating_setpoint: setpoint };
        break;

    case "small_bathroom":
        targetTopic = "zigbee2mqtt/Termostato_Bagnetto/set";
        targetPayload = { current_heating_setpoint: setpoint };
        break;

    default:
        node.warn("Comando App per termostato non mappato: " + room);
        return null;
}

return {
    topic: targetTopic,
    payload: targetPayload
};

let inTopic = msg.topic;
let targetRoom = "";
let targetTemp = null;
let baseTopic = global.get("app_base_topic") || "zara/android/domotica";

if (inTopic === "casa/clima/stato_completo") {
    targetRoom = "living";
    targetTemp = msg.payload.stato_condizionatore.temperatura_impostata_c;
    if (targetTemp === 0) return null; 
}
else if (inTopic.includes("zigbee2mqtt/Termostato_Bagno")) {
    targetRoom = "bathroom";
    targetTemp = (typeof msg.payload === 'object') ? msg.payload.current_heating_setpoint : parseFloat(msg.payload);
}
else if (inTopic.includes("zigbee2mqtt/Termostato_Bagnetto")) {
    targetRoom = "small_bathroom";
    targetTemp = (typeof msg.payload === 'object') ? msg.payload.current_heating_setpoint : parseFloat(msg.payload);
}

if (targetRoom !== "" && targetTemp !== null && !isNaN(targetTemp)) {
    return {
        topic: `${baseTopic}/thermostat/${targetRoom}/target/state`,
        payload: targetTemp
    };
}

return null;

let baseTopic = global.get("app_base_topic") || "zara/android/domotica";

let regexVmc = new RegExp(`^${baseTopic}/vmc/([^/]+)/set$`);
let match = msg.topic.match(regexVmc);

if (!match || !match[1]) return null;

let cmdType = match[1];

if (cmdType === "speed") {
    let speed = parseInt(msg.payload);

    if (isNaN(speed) || speed < 1 || speed > 4) {
        node.warn("Comando VMC scartato. Valore non valido: " + msg.payload);
        return null;
    }

    return {
        topic: "/esp8266/brink/fanspeed",
        payload: speed
    };
}

return null;

let inTopic = msg.topic;
let speed = null;
let baseTopic = global.get("app_base_topic") || "zara/android/domotica";

if (inTopic === "alexa/vmc") {
    speed = parseInt(msg.payload);
} else if (inTopic === "casa/clima/stato_completo") {
    if (msg.payload && msg.payload.stato_vmc) {
        speed = msg.payload.stato_vmc.velocita_attuale;
    }
}

if (speed !== null && !isNaN(speed)) {
    return {
        topic: `${baseTopic}/vmc/speed/state`,
        payload: speed.toString()
    };
}
return null;

// --- GATEWAY TELEMETRIE: AMBIENTI ---
let inTopic = msg.topic;
let rawPayload = msg.payload;

const APP_BASE = global.get("app_base_topic", "file") || "zara/android/domotica";

let messaggiInUscita = [];

switch (inTopic) {
    case "emon/emonth5/humidex":
        if (!isNaN(parseFloat(rawPayload))) {
            messaggiInUscita.push({ topic: `${APP_BASE}/env/humidexLiving`, payload: parseFloat(rawPayload).toString() });
        }
        break;
    case "emon/cameraMatrimoniale/humidex":
        if (!isNaN(parseFloat(rawPayload))) {
            messaggiInUscita.push({ topic: `${APP_BASE}/env/humidexBedroom`, payload: parseFloat(rawPayload).toString() });
        }
        break;
    case "emon/emonth5/temperature_calibrated":
        if (!isNaN(parseFloat(rawPayload))) {
            messaggiInUscita.push({ topic: `${APP_BASE}/env/tempLiving`, payload: parseFloat(rawPayload).toString() });
        }
        break;

    case "emon/emonth5/humidity":
        if (!isNaN(parseFloat(rawPayload))) {
            messaggiInUscita.push({ topic: `${APP_BASE}/env/humLiving`, payload: parseFloat(rawPayload).toString() });
        }
        break;

    case "emon/cameraMatrimoniale/temperature":
        if (!isNaN(parseFloat(rawPayload))) {
            messaggiInUscita.push({ topic: `${APP_BASE}/env/tempBedroom`, payload: parseFloat(rawPayload).toString() });
        }
        break;

    case "emon/cameraMatrimoniale/humidity":
        if (!isNaN(parseFloat(rawPayload))) {
            messaggiInUscita.push({ topic: `${APP_BASE}/env/humBedroom`, payload: parseFloat(rawPayload).toString() });
        }
        break;

    case "zigbee2mqtt/Sonoff AirGuard TH camera matrimoniale":
        if (typeof rawPayload === 'object') {
            if (rawPayload.temperature !== undefined) {
                messaggiInUscita.push({
                    topic: `${APP_BASE}/env/tempBedroom`,
                    payload: parseFloat(rawPayload.temperature).toString()
                });
            }
            if (rawPayload.humidity !== undefined) {
                messaggiInUscita.push({
                    topic: `${APP_BASE}/env/humBedroom`,
                    payload: rawPayload.humidity.toString()
                });
            }
        }
        break;
    case "zigbee2mqtt/Sonoff AirGuard TH esterno cucina":
        if (typeof rawPayload === 'object') {
            if (rawPayload.temperature !== undefined) {
                messaggiInUscita.push({
                    topic: `${APP_BASE}/env/tempOutdoor`,
                    payload: rawPayload.temperature.toString()
                });
            }
            if (rawPayload.humidity !== undefined) {
                messaggiInUscita.push({
                    topic: `${APP_BASE}/env/humOutdoor`,
                    payload: rawPayload.humidity.toString()
                });
            }
        }
        break;

    default:
        return null;
}

if (messaggiInUscita.length === 0) {
    return null; 
}

return [ messaggiInUscita ];

let baseTopic = global.get("app_base_topic", "file") || "zara/android/domotica";
let inTopic = msg.topic;
let rawPayload = msg.payload.toString().trim(); 

function parseBoolean(val) {
    if (val === "1" || val.toLowerCase() === "true") return true;
    if (val === "0" || val.toLowerCase() === "false") return false;
    return null;
}

let targetTopic = "";
let targetPayload = "";

switch (inTopic) {
    // AGGIUNTA: Gestione Range Temporale Periodo di Grazia
    case `${baseTopic}/system/time_range/set`:
        // Validazione regex: accetta formati come "8-16" o "08-16"
        if (/^\d{1,2}-\d{1,2}$/.test(rawPayload)) {
            global.set("grace_period_time_range", rawPayload, "file");
            targetTopic = "time_range";
            targetPayload = rawPayload;
        } else {
            node.warn("Time range ignorato: formato errato " + rawPayload);
        }
        break;

    case `${baseTopic}/system/enabled/state`:
        let sysEnabled = parseBoolean(rawPayload);
        if (sysEnabled !== null) {
            targetTopic = "system";
            targetPayload = sysEnabled;
        }
        break;

    case `${baseTopic}/system/holiday/set`:
        let holidayMode = parseBoolean(rawPayload);
        if (holidayMode !== null) {
            targetTopic = "holiday";
            targetPayload = holidayMode;
        }
        break;

    case `${baseTopic}/system/ac_auto/set`:
        let acAuto = parseBoolean(rawPayload);
        if (acAuto !== null) {
            targetTopic = "ACAUTO";
            targetPayload = acAuto;
        }
        break;

    case `${baseTopic}/system/luci_eco/set`:
        let ecoLights = parseBoolean(rawPayload);
        if (ecoLights !== null) {
            targetTopic = "luciECO";
            targetPayload = ecoLights;
        }
        break;

    case `${baseTopic}/system/luci_piscina_auto/set`:
        let poolAuto = parseBoolean(rawPayload);
        if (poolAuto !== null) {
            targetTopic = "luciPiscinaAUTO";
            targetPayload = poolAuto;
        }
        break;

    case `${baseTopic}/system/sensore_portico/set`:
        let porch_sensor = parseBoolean(rawPayload);
        if (porch_sensor !== null) {
            targetTopic = "porch_sensor";
            targetPayload = porch_sensor;
        }
        break;

    case `${baseTopic}/vmc/maxNightSpeed/state`:
        let maxSpeed = parseInt(rawPayload);
        if (!isNaN(maxSpeed) && maxSpeed >= 1 && maxSpeed <= 4) {
            targetTopic = "vmc_night_limit";
            targetPayload = maxSpeed;
        }
        break;

    default:
        return null;
}

if (targetTopic !== "") {
    return { topic: targetTopic, payload: targetPayload };
}

return null;

let topic = msg.topic;
let baseTopic = global.get("app_base_topic") || "zara/android/domotica";

if (!topic.startsWith(baseTopic)) return null;

let routingPath = topic.substring(baseTopic.length);

let outLuci = null;         
let outTermostati = null;   
let outVmc = null;          
let outSettaggi = null;     

if (routingPath.startsWith("/light/") || routingPath.startsWith("/scene/")) {
    outLuci = msg;
} 
else if (routingPath.startsWith("/thermostat/")) {
    outTermostati = msg;
} 
else if (routingPath.startsWith("/vmc/")) {
    if (routingPath.includes("/maxNightSpeed/set")) {
        outSettaggi = msg;
    } else {
        outVmc = msg;
    }
} 
else {
    outSettaggi = msg;
}

return [outLuci, outTermostati, outVmc, outSettaggi];

let currentTopic = global.get("app_base_topic", "file");
if (!currentTopic) {
    global.set("app_base_topic", "zara/android/domotica", "file");
    node.warn("App Base Topic inizializzato al default.");
}
return null;

// ============================================================================
// OUTBOUND ROUTER SETTAGGI
// Formatta i feedback hardware per aggiornare la UI dell'App Android
// ============================================================================

let inTopic = msg.topic;
let baseTopic = global.get("app_base_topic") || "zara/android/domotica";

// Helper per pulire la conversione verso l'app (0 = false, 1 = true)
const parseToBinary = (val) => (val === "true" || val === true || val === 1 || val === "1") ? 1 : 0;

if (inTopic === "zara/domotics/modalitavacanza") {
    return { 
        topic: `${baseTopic}/system/holiday/state`, 
        payload: parseToBinary(msg.payload) 
    };
}
else if (inTopic === "casa/clima/cmnd/AI_climate_enabling") {
    return { 
        topic: `${baseTopic}/system/set`, 
        payload: parseToBinary(msg.payload) 
    };
}
else if (inTopic === "zara/domotics/luciECO") {
    return { 
        topic: `${baseTopic}/system/luci_eco/state`, 
        payload: parseToBinary(msg.payload) 
    };
}
else if (inTopic === "zara/domotics/luciPiscinaAuto") {
    return { 
        topic: `${baseTopic}/system/luci_piscina_auto/state`, 
        payload: parseToBinary(msg.payload) 
    };
}
else if (inTopic === "zara/domotics/ACAuto") {
    return { 
        topic: `${baseTopic}/system/ac_auto/state`, 
        payload: parseToBinary(msg.payload) 
    };
}
else if (inTopic === "zara/domotics/porch_sensor") {
    return { 
        topic: `${baseTopic}/system/sensore_portico/state`, 
        payload: parseToBinary(msg.payload) 
    };
}
else if (inTopic === "casa/clima/stat/vmc_max_notte") {
    return { 
        topic: `${baseTopic}/vmc/maxNightSpeed/set`, 
        payload: msg.payload 
    };
}
else if (inTopic === "zara/domotics/time_range") {
    return { 
        topic: `${baseTopic}/system/time_range/state`, 
        payload: msg.payload 
    };
}

return null;

// Legge il valore in arrivo
let gridPower = parseFloat(msg.payload) || 0;

// Se il valore è tra -30W e +30W, lo forza a 0
if (Math.abs(gridPower) <= 30) {
    gridPower = 0;
}

// Passa il valore pulito al nodo MQTT
msg.payload = gridPower.toString();
return msg;

let baseTopic = global.get("app_base_topic", "file") || "zara/android/domotica";

// 1. Dati dalla stufa (ESP8266 -> App)
if (msg.topic.startsWith("zara/domotics/palazzetti/")) {
    let command = msg.topic.split('/').pop();
    let val = msg.payload !== undefined ? msg.payload.toString().toLowerCase() : "";
    let msgApp = null;

    if (command === "acceso") {
        let isOn = (val === "on" || val === "true" || val === "1");
        msgApp = { topic: `${baseTopic}/casa/stufa/stat/acceso`, payload: isOn };
    } else if (command === "modalita") {
        msgApp = { topic: `${baseTopic}/casa/stufa/stat/modalita`, payload: msg.payload };
    }

    if (msgApp) return [msgApp, null];
}

// 2. Comandi dall'App (App -> Stufa/Alexa)
/*
String inTopic_powerset = "/power";
String inTopic_command = "/command";
String inTopic_status = "/getstatus";
String outTopic = "/hello";
String outTopicLog = "/log/message";
String mqtt_client_id = "ESP8266-";
String mqtt_base_topic = "/esp8266/palazzetti";
*/
if (msg.topic.includes("alexa/caminetto")) {
    let command = msg.topic.split('/').pop();
    let val = msg.payload.toString();

    let msgLocal = null;
    let msgAlexa = null;

    if (command === "command") {
        let payloadAlexa = (val === "true" || val === "on") ? "on" : "off";
        msgAlexa = { topic: "alexa/caminetto/command", payload: payloadAlexa };
        msgLocal = { topic: `${baseTopic}/casa/stufa/stat/acceso`, payload: (payloadAlexa === "on") };
    } 
    else if (command === "power") {
        msgAlexa = { topic: "alexa/caminetto/power", payload: parseInt(val) };
        msgLocal = { topic: `${baseTopic}/casa/stufa/stat/potenza`, payload: parseInt(val) };
    } 
    else if (command === "modalita") {
        msgLocal = [
            // NOTA: Controlla che questo topic sia corretto per cambiare modalità nell'ESP8266
            { topic: "zara/domotics/palazzetti/set/modalita", payload: val }, 
            { topic: `${baseTopic}/casa/stufa/stat/modalita`, payload: val }
        ];
    }

    return [msgLocal, msgAlexa];
}

if (msg.topic.includes("emon/focolare/powerraw")) {
    let val = msg.payload.toString();
    let msgLocal = null;
    msgLocal = { topic: `${baseTopic}/casa/stufa/stat/potenza`, payload: parseInt(val) };
    return [msgLocal, null];
}

return null;

// Recupera il topic base dalla configurazione globale o usa il default
let baseTopic = global.get("app_base_topic") || "zara/android/domotica";

// Costruiamo il topic completo per la sottoscrizione (ascolto su tutta la gerarchia)
let subscriptionTopic = baseTopic + "/#";

// Creiamo il messaggio di comando per il nodo MQTT
// Il nodo MQTT con "Dynamic Subscription" accetta msg.action = 'subscribe'
let msg1 = {
    action: "subscribe",
    topic: subscriptionTopic,
    qos: 2
};

// Log per debug nel pannello di Node-RED
node.warn("Boot: Sottoscrizione dinamica attivata su topic: " + subscriptionTopic);

return msg1;

let baseTopic = global.get("app_base_topic", "file") || "zara/android/domotica";

return {
    topic: `${baseTopic}/history/ac/response`,
    payload: msg.payload // Inoltra direttamente l'array JSON del DB
};

// Recupera il prefisso dinamico dalla memoria
let baseTopic = global.get("app_base_topic", "file") || "zara/android/domotica";

// Costruisce il topic esatto per la richiesta dello storico
let topicRichiesta = baseTopic + "/history/ac/request";

// Crea il payload formattato per dire al nodo MQTT di iscriversi
let msgg = {
    action: "subscribe",
    topic: topicRichiesta,
    qos: 2
};

node.warn("Boot: In attesa di richieste storico su: " + topicRichiesta);

return msgg;
